package cc.ataglace.molebutter.marketplaceesm.internal.product;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
import java.util.*;
import tools.jackson.databind.*;
import tools.jackson.databind.node.*;
import cc.ataglace.molebutter.marketplace.api.*;
class EsmProductMappingTest {
    final ObjectMapper json=new ObjectMapper();final EsmProductMapping mapping=new EsmProductMapping(json);
    PartnerEditor.Input input(String price,String stock){var fields=new LinkedHashMap<String,Object>();for(var f:EsmProductMapping.schema().fields())fields.put(f.key(),switch(f.type()){case "number"->"1";case "select"->"false";default->"code";});fields.put("itemBasicInfo.goodsName.kor","상품");return new PartnerEditor.Input(fields,List.of(new PartnerEditor.Option("00000000-0000-0000-0000-000000000001","기본 상품","seller-code",price,stock,List.of(),true)),List.of(new PartnerEditor.Image("00000000-0000-0000-0000-000000000002",null,"https://img.example/a.jpg",true,0)),"<p>설명</p>","notice",List.of(new MarketplaceDrafts.Attribute("material","가죽")),List.of());}
    @Test void jointCreateContainsBothCategoriesWithoutLegacyConversionIds(){var body=mapping.write(input("10000","1"),null,Set.of("GMARKET","AUCTION"),PartnerEditor.Image::url);assertThat(body.path("itemBasicInfo").path("category").path("site").size()).isEqualTo(2);assertThat(body.path("itemAddtionalInfo").path("price").path("Gmkt").asLong()).isEqualTo(10000);assertThat(body.path("itemAddtionalInfo").path("price").path("Iac").asLong()).isEqualTo(10000);assertThat(body.has("siteGoodsNo")).isFalse();assertThat(body.has("isSell")).isFalse();assertThat(body.path("itemAddtionalInfo").path("images").path("basicImgURL").asString()).isEqualTo("https://img.example/a.jpg");}
    @Test void enforcesProviderPriceAndZeroStockRules(){assertThatThrownBy(()->mapping.write(input("10001","1"),null,Set.of("GMARKET"),PartnerEditor.Image::url)).hasMessageContaining("10원 단위");assertThatThrownBy(()->mapping.write(input("10000","0"),null,Set.of("GMARKET"),PartnerEditor.Image::url)).hasMessageContaining("재고");}
    @Test void observesStableOptionUuidAndLocksUneditableName(){var source=mapping.write(input("10000","1"),null,Set.of("GMARKET"),PartnerEditor.Image::url);source.put("isEditableGoodsName",false);var a=mapping.read(source,"123","GMARKET");var b=mapping.read(source,"123","GMARKET");assertThat(a.input().options().getFirst().id()).isEqualTo(b.input().options().getFirst().id());assertThat(a.readonlyFields()).contains("fields.itemBasicInfo.goodsName.kor");var changed=new LinkedHashMap<>(a.input().fields());changed.put("itemBasicInfo.goodsName.kor","변경");var i=a.input();assertThatThrownBy(()->mapping.write(new PartnerEditor.Input(changed,i.options(),i.images(),i.description(),i.noticeType(),i.notices(),i.certifications()),source,Set.of("GMARKET"),PartnerEditor.Image::url)).hasMessageContaining("상품명");}
    @Test void updatePreservesOtherSiteSaleStateAndUnknownFields(){var source=mapping.write(input("10000","1"),null,Set.of("GMARKET","AUCTION"),PartnerEditor.Image::url);source.set("isSell",json.valueToTree(Map.of("gmkt",false,"iac",true)));source.put("unknownProviderField","keep");var before=source.deepCopy();var result=mapping.write(input("11000","2"),source,Set.of("GMARKET","AUCTION"),PartnerEditor.Image::url);assertThat(result.path("isSell")).isEqualTo(source.path("isSell"));assertThat(result.path("unknownProviderField").asString()).isEqualTo("keep");assertThat(source).isEqualTo(before);}
}
